/* Automated test driver for Lab 09. DO NOT EDIT THIS FILE. */
public class Lab09ArrayStatsTest {

    public static void main(String[] args) {

        int[] scores = {88, 92, 79, 95, 61};
        int[] single = {42};
        int[] empty = {};
        int[] negatives = {-5, -30, -1, -12};
        int[] tied = {7, 9, 9, 3};

        TestRunner.section("sum");
        TestRunner.check("sum of the sample scores", 415, Lab09ArrayStats.sum(scores));
        TestRunner.check("sum of one element", 42, Lab09ArrayStats.sum(single));
        TestRunner.check("sum of an empty array", 0, Lab09ArrayStats.sum(empty));
        TestRunner.check("sum of negatives", -48, Lab09ArrayStats.sum(negatives));

        TestRunner.section("average");
        TestRunner.checkNear("average of the sample scores", 83.0, Lab09ArrayStats.average(scores), 1e-9);
        TestRunner.checkNear("average of {7,9,9,3} is not truncated",
                7.0, Lab09ArrayStats.average(tied), 1e-9);
        TestRunner.checkNear("average of an empty array is guarded",
                0.0, Lab09ArrayStats.average(empty), 1e-9);

        TestRunner.section("indexOfMax");
        TestRunner.check("largest of the sample scores is at index 3", 3, Lab09ArrayStats.indexOfMax(scores));
        TestRunner.check("single element", 0, Lab09ArrayStats.indexOfMax(single));
        TestRunner.check("first occurrence wins on a tie", 1, Lab09ArrayStats.indexOfMax(tied));
        TestRunner.check("all negative values", 2, Lab09ArrayStats.indexOfMax(negatives));
        TestRunner.check("empty array returns -1", -1, Lab09ArrayStats.indexOfMax(empty));

        TestRunner.section("linearSearch");
        TestRunner.check("79 is at index 2", 2, Lab09ArrayStats.linearSearch(scores, 79));
        TestRunner.check("88 is at index 0", 0, Lab09ArrayStats.linearSearch(scores, 88));
        TestRunner.check("61 is at the last index", 4, Lab09ArrayStats.linearSearch(scores, 61));
        TestRunner.check("100 is absent", -1, Lab09ArrayStats.linearSearch(scores, 100));
        TestRunner.check("first match is returned", 1, Lab09ArrayStats.linearSearch(tied, 9));

        TestRunner.section("reversed");
        TestRunner.checkArray("reverse of the sample scores",
                new int[]{61, 95, 79, 92, 88}, Lab09ArrayStats.reversed(scores));
        TestRunner.checkArray("the original array was NOT modified",
                new int[]{88, 92, 79, 95, 61}, scores);
        TestRunner.checkArray("reverse of one element", new int[]{42}, Lab09ArrayStats.reversed(single));
        TestRunner.checkArray("reverse of an empty array", new int[]{}, Lab09ArrayStats.reversed(empty));

        TestRunner.section("countAbove");
        TestRunner.check("scores above 83.0", 3, Lab09ArrayStats.countAbove(scores, 83.0));
        TestRunner.check("threshold equal to an element is exclusive", 2, Lab09ArrayStats.countAbove(scores, 88));
        TestRunner.check("nothing above 100", 0, Lab09ArrayStats.countAbove(scores, 100));
        TestRunner.check("everything above -100", 5, Lab09ArrayStats.countAbove(scores, -100));

        TestRunner.exitWithSummary();
    }
}
